<PageTitle>Dispatcher Dashboard</PageTitle>

<div class="container-fluid">
    <div class="d-flex justify-content-between align-items-center mb-3">
        <h2>📋 Dispatcher Dashboard</h2>
        <button class="btn btn-success" @onclick="ShowCreateForm">➕ New Shipment</button>
    </div>

    <!-- Filters -->
    <div class="row mb-3 g-2">
        <div class="col-md-3">
            <input type="text" class="form-control" placeholder="Search by tracking #, sender, or recipient..."
                   @bind="searchFilter" @bind:event="oninput" />
        </div>
        <div class="col-md-2">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </div>

    @if (isLoading)
    {
        <div class="text-center p-5">
            <div class="spinner-border text-primary" role="status"></div>
            <p class="mt-2">Loading shipments...</p>
        </div>
    }
    else if (errorMessage is not null)
    {
        <div class="alert alert-danger">@errorMessage</div>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Sender</th>
                        <th>Recipient</th>
                        <th>Weight</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in FilteredShipments)
                    {
                        <tr>
                            <td><strong>@s.TrackingNumber</strong></td>
                            <td>@s.Origin</td>
                            <td>@s.Destination</td>
                            <td>@s.SenderName</td>
                            <td>@s.RecipientName</td>
                            <td>@s.WeightKg kg</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                            <td>
                                <div class="btn-group btn-group-sm">
                                    <select class="form-select form-select-sm" style="width: auto;"
                                            value="@s.Status" @onchange="e => UpdateStatus(s, e)">
                                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@status" selected="@(status == s.Status)">@status</option>
                                        }
                                    </select>
                                </div>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
        <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
    }

    @if (showCreateForm)
    {
        <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
            <div class="modal-dialog modal-lg">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Create New Shipment</h5>
                        <button type="button" class="btn-close" @onclick="CloseCreateForm"></button>
                    </div>
                    <div class="modal-body">
                        <div class="row g-3">
                            <div class="col-md-6">
                                <label class="form-label">Origin</label>
                                <input type="text" class="form-control" @bind="newShipment.Origin" placeholder="e.g. New York, NY" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Destination</label>
                                <input type="text" class="form-control" @bind="newShipment.Destination" placeholder="e.g. Los Angeles, CA" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Sender Name</label>
                                <input type="text" class="form-control" @bind="newShipment.SenderName" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Recipient Name</label>
                                <input type="text" class="form-control" @bind="newShipment.RecipientName" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">Weight (kg)</label>
                                <input type="number" class="form-control" @bind="newShipment.WeightKg" step="0.1" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">Estimated Delivery</label>
                                <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                            </div>
                            <div class="col-12">
                                <label class="form-label">Notes</label>
                                <textarea class="form-control" @bind="newShipment.Notes" rows="2"></textarea>
                            </div>
                        </div>
                        @if (createError is not null)
                        {
                            <div class="alert alert-danger mt-3">@createError</div>
                        }
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CloseCreateForm">Cancel</button>
                        <button class="btn btn-primary" @onclick="CreateShipment" disabled="@isCreating">
                            @if (isCreating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                            Create Shipment
                        </button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private string? errorMessage;
    private string searchFilter = string.Empty;
    private string statusFilter = string.Empty;
    private bool showCreateForm;
    private ShipmentDto newShipment = new();
    private bool isCreating;
    private string? createError;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrWhiteSpace(searchFilter))
        {
            var q = searchFilter.ToLowerInvariant();
            if (!s.TrackingNumber.Contains(q, StringComparison.OrdinalIgnoreCase) &&
                !s.SenderName.Contains(q, StringComparison.OrdinalIgnoreCase) &&
                !s.RecipientName.Contains(q, StringComparison.OrdinalIgnoreCase) &&
                !s.Destination.Contains(q, StringComparison.OrdinalIgnoreCase))
                return false;
        }
        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var fs))
        {
            if (s.Status != fs) return false;
        }
        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            errorMessage = "Failed to load shipments. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            if (updated is not null)
            {
                var idx = shipments.FindIndex(s => s.Id == shipment.Id);
                if (idx >= 0) shipments[idx] = updated;
            }
        }
    }

    private void ShowCreateForm()
    {
        newShipment = new ShipmentDto { EstimatedDelivery = DateTime.UtcNow.AddDays(7) };
        createError = null;
        showCreateForm = true;
    }

    private void CloseCreateForm() => showCreateForm = false;

    private void ClearFilters()
    {
        searchFilter = string.Empty;
        statusFilter = string.Empty;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination) ||
            string.IsNullOrWhiteSpace(newShipment.SenderName) || string.IsNullOrWhiteSpace(newShipment.RecipientName))
        {
            createError = "Please fill in all required fields.";
            return;
        }

        isCreating = true;
        createError = null;
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments.Insert(0, created);
            showCreateForm = false;
        }
        catch
        {
            createError = "Failed to create shipment. Please try again.";
        }
        finally
        {
            isCreating = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}
