        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchQuery.Trim());
            if (shipment is null)
                errorMessage = $"No shipment found with tracking number \"{searchQuery}\".";
        }
        catch
        {
            errorMessage = "An error occurred while searching. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
