@code {
    private List<ShipmentDto> shipments = [];
    private bool isLoading = true;
    private string? errorMessage;
    private string searchFilter = string.Empty;
    private string statusFilter = string.Empty;
    private bool showCreateForm;
    private ShipmentDto newShipment = new();
    private bool isCreating;
    private string? createError;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments.Where(s =>
    {
        if (!string.IsNullOrWhiteSpace(searchFilter))
        {
            var q = searchFilter.ToLowerInvariant();
            if (!s.TrackingNumber.Contains(q, StringComparison.OrdinalIgnoreCase) &&
                !s.SenderName.Contains(q, StringComparison.OrdinalIgnoreCase) &&
                !s.RecipientName.Contains(q, StringComparison.OrdinalIgnoreCase) &&
                !s.Destination.Contains(q, StringComparison.OrdinalIgnoreCase))
                return false;
        }
        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var fs))
        {
            if (s.Status != fs) return false;
        }
        return true;
    });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            errorMessage = "Failed to load shipments. Please try again.";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            if (updated is not null)
            {
                var idx = shipments.FindIndex(s => s.Id == shipment.Id);
                if (idx >= 0) shipments[idx] = updated;
            }
        }
    }

    private void ShowCreateForm()
    {
        newShipment = new ShipmentDto { EstimatedDelivery = DateTime.UtcNow.AddDays(7) };
        createError = null;
        showCreateForm = true;
    }

    private void CloseCreateForm() => showCreateForm = false;

    private void ClearFilters()
    {
        searchFilter = string.Empty;
        statusFilter = string.Empty;
    }

    private async Task CreateShipment()
    {
        if (string.IsNullOrWhiteSpace(newShipment.Origin) || string.IsNullOrWhiteSpace(newShipment.Destination) ||
            string.IsNullOrWhiteSpace(newShipment.SenderName) || string.IsNullOrWhiteSpace(newShipment.RecipientName))
        {
            createError = "Please fill in all required fields.";
            return;
        }

        isCreating = true;
        createError = null;
        try
        {
            var created = await ShipmentService.CreateShipmentAsync(newShipment);
            shipments.Insert(0, created);
            showCreateForm = false;
        }
        catch
        {
            createError = "Failed to create shipment. Please try again.";
        }
        finally
        {
            isCreating = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

